BEGIN;

SET LOCAL TIME ZONE 'Australia/Melbourne';

DO $seed$
DECLARE
  v_today date := (now() AT TIME ZONE 'Australia/Melbourne')::date;
  v_session_count integer;
BEGIN
  TRUNCATE TABLE
    public.impersonation_log,
    public.concerns,
    public.parent_messages,
    public.student_notes,
    public.student_feedback,
    public.feedback_raw,
    public.credit_ledger,
    public.attendance,
    public.session_students,
    public.sessions,
    public.enrollments,
    public.class_slots,
    public.classes,
    public.courses,
    public.students,
    public.parents,
    public.profiles
  RESTART IDENTITY CASCADE;

  DELETE FROM auth.identities
   WHERE user_id IN (
     '00000000-0000-4000-8000-000000000001',
     '00000000-0000-4000-8000-000000000002',
     '00000000-0000-4000-8000-000000000003',
     '00000000-0000-4000-8000-000000000011',
     '00000000-0000-4000-8000-000000000012',
     '00000000-0000-4000-8000-000000000013'
   );

  DELETE FROM auth.users
   WHERE id IN (
     '00000000-0000-4000-8000-000000000001',
     '00000000-0000-4000-8000-000000000002',
     '00000000-0000-4000-8000-000000000003',
     '00000000-0000-4000-8000-000000000011',
     '00000000-0000-4000-8000-000000000012',
     '00000000-0000-4000-8000-000000000013'
   );

  WITH accounts(id, email, display_name) AS (
    VALUES
      ('00000000-0000-4000-8000-000000000001'::uuid, 'boss@tutlab.local',  'Boss'),
      ('00000000-0000-4000-8000-000000000002'::uuid, 'kiki@tutlab.local',  'Kiki'),
      ('00000000-0000-4000-8000-000000000003'::uuid, 'jason@tutlab.local', 'Jason'),
      ('00000000-0000-4000-8000-000000000011'::uuid, 'kevin@tutlab.local', 'Kevin'),
      ('00000000-0000-4000-8000-000000000012'::uuid, 'lisa@tutlab.local',  'Lisa'),
      ('00000000-0000-4000-8000-000000000013'::uuid, 'amy@tutlab.local',   'Amy')
  )
  INSERT INTO auth.users (
    instance_id,
    id,
    aud,
    role,
    email,
    encrypted_password,
    email_confirmed_at,
    recovery_sent_at,
    last_sign_in_at,
    raw_app_meta_data,
    raw_user_meta_data,
    created_at,
    updated_at,
    confirmation_token,
    email_change,
    email_change_token_new,
    recovery_token
  )
  SELECT
    '00000000-0000-0000-0000-000000000000'::uuid,
    id,
    'authenticated',
    'authenticated',
    email,
    extensions.crypt('Passw0rd!', extensions.gen_salt('bf')),
    now(),
    now(),
    now(),
    '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('display_name', display_name),
    now(),
    now(),
    '',
    '',
    '',
    ''
  FROM accounts;

  WITH accounts(id, email) AS (
    VALUES
      ('00000000-0000-4000-8000-000000000001'::uuid, 'boss@tutlab.local'),
      ('00000000-0000-4000-8000-000000000002'::uuid, 'kiki@tutlab.local'),
      ('00000000-0000-4000-8000-000000000003'::uuid, 'jason@tutlab.local'),
      ('00000000-0000-4000-8000-000000000011'::uuid, 'kevin@tutlab.local'),
      ('00000000-0000-4000-8000-000000000012'::uuid, 'lisa@tutlab.local'),
      ('00000000-0000-4000-8000-000000000013'::uuid, 'amy@tutlab.local')
  )
  INSERT INTO auth.identities (
    id,
    user_id,
    provider_id,
    identity_data,
    provider,
    last_sign_in_at,
    created_at,
    updated_at
  )
  SELECT
    id,
    id,
    email,
    jsonb_build_object(
      'sub', id::text,
      'email', email,
      'email_verified', true,
      'phone_verified', false
    ),
    'email',
    now(),
    now(),
    now()
  FROM accounts;

