  WITH future_session_ids(slot_id, session_id) AS (
    VALUES
      ('00000000-0000-4000-8000-000000000301'::uuid, '00000000-0000-4000-8000-000000004101'::uuid),
      ('00000000-0000-4000-8000-000000000302'::uuid, '00000000-0000-4000-8000-000000004102'::uuid),
      ('00000000-0000-4000-8000-000000000303'::uuid, '00000000-0000-4000-8000-000000004103'::uuid),
      ('00000000-0000-4000-8000-000000000304'::uuid, '00000000-0000-4000-8000-000000004104'::uuid),
      ('00000000-0000-4000-8000-000000000305'::uuid, '00000000-0000-4000-8000-000000004105'::uuid),
      ('00000000-0000-4000-8000-000000000306'::uuid, '00000000-0000-4000-8000-000000004106'::uuid),
      ('00000000-0000-4000-8000-000000000307'::uuid, '00000000-0000-4000-8000-000000004107'::uuid),
      ('00000000-0000-4000-8000-000000000308'::uuid, '00000000-0000-4000-8000-000000004108'::uuid),
      ('00000000-0000-4000-8000-000000000309'::uuid, '00000000-0000-4000-8000-000000004109'::uuid),
      ('00000000-0000-4000-8000-000000000310'::uuid, '00000000-0000-4000-8000-000000004110'::uuid)
  )
  INSERT INTO public.sessions (
    id, class_id, teacher_id, starts_at, ends_at, status
  )
  SELECT
    ids.session_id,
    cs.class_id,
    c.teacher_id,
    (((v_today + days.day_offset) + cs.start_time) AT TIME ZONE 'Australia/Melbourne'),
    (((v_today + days.day_offset) + cs.end_time) AT TIME ZONE 'Australia/Melbourne'),
    'planned'
  FROM public.class_slots cs
  JOIN public.classes c ON c.id = cs.class_id
  JOIN future_session_ids ids ON ids.slot_id = cs.id
  CROSS JOIN generate_series(1, 7) AS days(day_offset)
  WHERE cs.weekday = (EXTRACT(ISODOW FROM (v_today + days.day_offset))::integer % 7);

  INSERT INTO public.session_students (session_id, student_id, is_new, is_trial)
  SELECT
    s.id,
    e.student_id,
    s.id = '00000000-0000-4000-8000-000000004001'
      AND e.student_id = '00000000-0000-4000-8000-000000001001',
    s.id = '00000000-0000-4000-8000-000000004001'
      AND e.student_id = '00000000-0000-4000-8000-000000001002'
  FROM public.sessions s
  JOIN public.enrollments e ON e.class_id = s.class_id
  WHERE e.status = 'active'
    AND e.start_date <= (s.starts_at AT TIME ZONE 'Australia/Melbourne')::date
    AND (
      e.end_date IS NULL
      OR e.end_date >= (s.starts_at AT TIME ZONE 'Australia/Melbourne')::date
    );

